UPDATE tools SET faq = $x$[{"q": "What is Framer AI?", "a": "Framer AI is a website builder where you describe your site in text and AI generates a complete, styled website. You can then edit the design visually, add CMS content, and publish to a live URL with a custom domain. It bridges the gap between AI generation and professional web design."}, {"q": "Can Canva build a website?", "a": "Canva has a basic website builder feature, but it's limited compared to dedicated website builders like Framer or Webflow. Canva websites lack advanced animations, CMS functionality, and design control. Canva is best for graphics; Framer is better for actual websites."}, {"q": "Is Framer AI free?", "a": "Framer has a free plan with 500 AI credits to try Agents, a free Framer domain, and non-commercial use limits. Paid tiers are Basic ($10) and Pro ($30) as listed on Framer's pricing page, plus a custom-priced Enterprise plan; the exact billing-cycle cost is confirmed at checkout. AI generation on every plan is metered by credits rather than unlimited."}]$x$::jsonb
 WHERE slug = 'framer-ai' AND lang = 'en';

