UPDATE tools SET faq = $x$[{"q": "¿Qué es Framer AI?", "a": "Framer AI es un creador de sitios web donde describes tu sitio en texto y la IA genera un sitio web completo y con estilo. Luego puedes editar el diseño visualmente, añadir contenido de CMS y publicarlo en una URL en vivo con un dominio personalizado. Cierra la brecha entre la generación por IA y el diseño web profesional."}, {"q": "¿Puede Canva crear un sitio web?", "a": "Canva tiene una función básica de creador de sitios web, pero es limitada en comparación con creadores de sitios dedicados como Framer o Webflow. Los sitios de Canva carecen de animaciones avanzadas, funcionalidad de CMS y control de diseño. Canva es mejor para gráficos; Framer es mejor para sitios web reales."}, {"q": "¿Es gratis Framer AI?", "a": "Framer tiene un plan gratuito con 500 créditos de IA para probar Agents, un dominio gratuito de Framer y límites de uso no comercial. Los niveles de pago son Basic (10 $) y Pro (30 $) según lo indicado en la página de precios de Framer, además de un plan Enterprise con precio personalizado; el coste exacto del ciclo de facturación se confirma al finalizar la compra. La generación por IA en todos los planes se mide por créditos en lugar de ser ilimitada."}]$x$::jsonb
