UPDATE tools SET faq = $x$[{"q": "Was ist Framer AI?", "a": "Framer AI ist ein Website-Builder, bei dem man seine Website in Textform beschreibt und die KI eine vollständige, gestaltete Website erzeugt. Anschließend lässt sich das Design visuell bearbeiten, CMS-Inhalte hinzufügen und auf einer Live-URL mit eigener Domain veröffentlichen. Es verbindet KI-Generierung mit professionellem Webdesign."}, {"q": "Kann Canva eine Website erstellen?", "a": "Canva bietet eine grundlegende Website-Builder-Funktion, die jedoch im Vergleich zu dedizierten Website-Buildern wie Framer oder Webflow eingeschränkt ist. Canva-Websites verfügen nicht über erweiterte Animationen, CMS-Funktionalität und Designkontrolle. Canva eignet sich am besten für Grafiken; Framer eher für echte Websites."}, {"q": "Ist Framer AI kostenlos?", "a": "Framer bietet einen kostenlosen Plan mit 500 KI-Credits zum Ausprobieren der Agents, einer kostenlosen Framer-Domain und Einschränkungen für nicht-kommerzielle Nutzung. Bezahlte Stufen sind Basic (10 $) und Pro (30 $), wie auf Framers Preisseite aufgeführt, sowie ein individuell bepreister Enterprise-Plan; die genauen Kosten pro Abrechnungszeitraum werden beim Checkout bestätigt. Die KI-Generierung wird in allen Plänen über Credits abgerechnet und ist nicht unbegrenzt."}]$x$::jsonb
