UPDATE tools SET faq = $x$[{"q": "O que é o Framer AI?", "a": "O Framer AI é um construtor de sites em que você descreve seu site em texto e a IA gera um site completo e estilizado. Em seguida, você pode editar o design visualmente, adicionar conteúdo via CMS e publicar em uma URL ativa com domínio personalizado. Ele faz a ponte entre a geração por IA e o design web profissional."}, {"q": "O Canva consegue criar um site?", "a": "O Canva tem um recurso básico de construtor de sites, mas é limitado em comparação com construtores dedicados como Framer ou Webflow. Os sites do Canva não têm animações avançadas, funcionalidade de CMS nem controle de design completo. O Canva é melhor para gráficos; o Framer é melhor para sites de verdade."}, {"q": "O Framer AI é gratuito?", "a": "O Framer tem um plano gratuito com 500 créditos de IA para experimentar os Agents, um domínio Framer gratuito e limites de uso não comercial. Os planos pagos são Basic ($10) e Pro ($30), conforme listado na página de preços da Framer, além de um plano Enterprise com preço personalizado; o custo exato do ciclo de cobrança é confirmado no checkout. A geração por IA em todos os planos é medida por créditos, em vez de ilimitada."}]$x$::jsonb
 WHERE slug = 'framer-ai' AND lang = 'pt';

UPDATE tools SET best_for = $x$Free AI UI design and prototyping from text, voice or image prompts, with infinite canvas$x$
