UPDATE tools SET faq = $x$[{"q": "What is Google Stitch?", "a": "Google Stitch is Google's AI UI design tool that generates app interfaces and prototypes from text, voice or image prompts. It features an infinite canvas for design exploration and launched as a free Google Labs experiment. Stitch is designed to make UI prototyping accessible to developers and non-designers without Figma experience."}, {"q": "Is Google Stitch free?", "a": "Google Stitch launched as a free Google Labs experiment with no paid tier. It's available at stitch.withgoogle.com. As a Google Labs product, pricing and availability may change as it develops, and current tier details are not published on the site."}, {"q": "Can Google Stitch export to Figma?", "a": "Yes. Google's 2025 launch described pasting designs into Figma and exporting front-end code. The May 2026 update added further export options, including Google Antigravity, Netlify publishing and shareable links via Google AI Studio."}, {"q": "Is Google Stitch better than Uizard?", "a": "Both are designed for non-designers to create UI prototypes quickly. Google Stitch has the advantage of launching as a free, Google-backed Labs experiment. Uizard is more established with more templates and a larger user community. Stitch's infinite canvas is unique for exploring many design variations simultaneously."}]$x$::jsonb
 WHERE slug = 'google-stitch' AND lang = 'en';

UPDATE tools SET best_for = $x$Diseño de interfaces de IA y prototipado gratuitos a partir de indicaciones de texto, voz o imagen, con lienzo infinito$x$
