UPDATE tools SET faq = $x$[{"q": "Что такое Google Stitch?", "a": "Google Stitch — это инструмент дизайна интерфейсов на базе ИИ от Google, который генерирует интерфейсы приложений и прототипы из текстовых, голосовых или графических запросов. Он включает бесконечный холст для изучения вариантов дизайна и был запущен как бесплатный эксперимент Google Labs. Stitch призван сделать прототипирование UI доступным для разработчиков и людей без опыта дизайна и работы с Figma."}, {"q": "Google Stitch бесплатен?", "a": "Google Stitch был запущен как бесплатный эксперимент Google Labs без платного тарифа. Он доступен на stitch.withgoogle.com. Как продукт Google Labs, цены и доступность могут меняться по мере его развития, а текущие сведения о тарифах на сайте не опубликованы."}, {"q": "Может ли Google Stitch экспортировать в Figma?", "a": "Да. При запуске в 2025 году Google описывал вставку дизайнов в Figma и экспорт front-end кода. Обновление в мае 2026 года добавило дополнительные варианты экспорта, включая Google Antigravity, публикацию через Netlify и общие ссылки через Google AI Studio."}, {"q": "Google Stitch лучше, чем Uizard?", "a": "Оба инструмента предназначены для того, чтобы люди без опыта дизайна могли быстро создавать прототипы UI. Преимущество Google Stitch в том, что он запущен как бесплатный эксперимент Google Labs при поддержке Google. Uizard более устоявшийся продукт с большим количеством шаблонов и более крупным сообществом пользователей. Бесконечный холст Stitch уникален тем, что позволяет одновременно изучать множество вариантов дизайна."}]$x$::jsonb
 WHERE slug = 'google-stitch' AND lang = 'ru';

