UPDATE tools SET faq = $x$[{"q": "Qu'est-ce que Google Stitch ?", "a": "Google Stitch est l'outil de design UI par IA de Google qui génère des interfaces d'application et des prototypes à partir de prompts texte, voix ou image. Il propose un canevas infini pour l'exploration de designs et a été lancé comme une expérience gratuite de Google Labs. Stitch est conçu pour rendre le prototypage UI accessible aux développeurs et aux non-designers sans expérience de Figma."}, {"q": "Google Stitch est-il gratuit ?", "a": "Google Stitch a été lancé comme une expérience gratuite de Google Labs, sans offre payante. Il est disponible sur stitch.withgoogle.com. En tant que produit Google Labs, la tarification et la disponibilité peuvent évoluer avec son développement, et les détails actuels sur les niveaux d'offre ne sont pas publiés sur le site."}, {"q": "Google Stitch peut-il exporter vers Figma ?", "a": "Oui. Le lancement de Google en 2025 décrivait le collage de designs dans Figma et l'export de code front-end. La mise à jour de mai 2026 a ajouté d'autres options d'export, notamment Google Antigravity, la publication Netlify et des liens partageables via Google AI Studio."}, {"q": "Google Stitch est-il meilleur qu'Uizard ?", "a": "Les deux outils sont conçus pour permettre aux non-designers de créer rapidement des prototypes UI. Google Stitch a l'avantage d'être une expérience Google Labs gratuite et soutenue par Google. Uizard est plus établi, avec davantage de modèles et une communauté d'utilisateurs plus large. Le canevas infini de Stitch est unique pour explorer simultanément de nombreuses variantes de design."}]$x$::jsonb
 WHERE slug = 'google-stitch' AND lang = 'fr';

