UPDATE tools SET faq = $x$[{"q": "O que é o Google Stitch?", "a": "Google Stitch é a ferramenta de design de UI com IA do Google que gera interfaces de aplicativos e protótipos a partir de prompts de texto, voz ou imagem. Ela conta com uma tela infinita para exploração de design e foi lançada como um experimento gratuito do Google Labs. O Stitch foi projetado para tornar a prototipagem de UI acessível a desenvolvedores e pessoas sem experiência em design, sem necessidade de conhecimento do Figma."}, {"q": "O Google Stitch é gratuito?", "a": "O Google Stitch foi lançado como um experimento gratuito do Google Labs, sem camada paga. Está disponível em stitch.withgoogle.com. Como produto do Google Labs, o preço e a disponibilidade podem mudar conforme evolui, e os detalhes atuais de planos não são publicados no site."}, {"q": "O Google Stitch pode exportar para o Figma?", "a": "Sim. O lançamento do Google em 2025 descrevia a possibilidade de colar designs no Figma e exportar código front-end. A atualização de maio de 2026 adicionou mais opções de exportação, incluindo Google Antigravity, publicação no Netlify e links compartilháveis via Google AI Studio."}, {"q": "O Google Stitch é melhor que o Uizard?", "a": "Ambos são projetados para que pessoas sem experiência em design criem protótipos de UI rapidamente. O Google Stitch tem a vantagem de ser lançado como um experimento gratuito do Google Labs, com o respaldo do Google. O Uizard é mais estabelecido, com mais modelos e uma comunidade de usuários maior. A tela infinita do Stitch é algo único para explorar várias variações de design simultaneamente."}]$x$::jsonb
 WHERE slug = 'google-stitch' AND lang = 'pt';

